DELETE FROM dbo.TWK_SCHEDULE_CONFIRM
WHERE OFFICE_CODE = #{LOGIN_OFFICE_CODE}
  AND SC_DATE = #{SC_DATE}
  AND CONFIRM_SEQ = #{CONFIRM_SEQ}
  AND DUTY_CD = #{DUTY_CD}
  AND REAL_USER_ID = #{LOGIN_ID}
  AND REAL_USER_NM = #{LOGIN_NAME}

DELETE FROM dbo.TMN_CONFIRM
WHERE OFFICE_CODE = #{LOGIN_OFFICE_CODE}
  AND MINWON_DATE = #{SC_DATE}
  AND CONFIRM_SEQ = #{CONFIRM_SEQ}
  AND DUTY_CD = #{DUTY_CD}
  AND REAL_USER_ID = #{LOGIN_ID}
  AND REAL_USER_NM = #{LOGIN_NAME}
